insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('f949b95a-edb7-45a2-9813-532736b1194c', '418b6293-cfe9-4313-93b8-f84f1bcd95b5', $$inleiding: groei van het aantal zzp'ers; Lorenzcurve primaire en secundaire inkomens$$,
   $$economie-vwo-2022-ii-zelfstandigen-zonder-personeel-context1.png$$,
   $$Onderzoekers Jan en Samira analyseren de groei van de groep zelfstandigen zonder personeel (zzp’ers) in een land. De groei betreft zowel het aantal zzp’ers als hun aandeel in de beroepsbevolking. In de juridische of ICT-sector werken zzp’ers met hoge uurtarieven, maar in de horeca, postbezorging of de schoonmaaksector werken veel zelfstandigen voor lage uurtarieven. Een aanzienlijk deel van de zzp’ers leeft onder of rond de armoedegrens. Jan heeft daarom een Lorenzcurve opgesteld van de primaire en secundaire inkomensverdeling van de zzp’ers in 2019.$$, 'inline'),
  ('eed39c77-4f25-4ebc-9467-61eccf9b6e48', '418b6293-cfe9-4313-93b8-f84f1bcd95b5', $$kanttekening van Samira bij de Lorenzcurve van de primaire inkomens$$,
   $$economie-vwo-2022-ii-zelfstandigen-zonder-personeel-context2.png$$,
   $$Samira plaatst een kanttekening: “De Lorenzcurve van de primaire inkomensverdeling is niet helemaal correct geschetst, want als bijvoorbeeld het laagste kwintiel van de zzp’ers in 2019 een te laag uurtarief heeft om kostendekkend te zijn, klopt de curve niet.”$$, 'inline'),
  ('86bcfbb0-99b1-476b-84ad-01d81d5f022d', '418b6293-cfe9-4313-93b8-f84f1bcd95b5', $$figuur 1: Lorenzcurven van zzp'ers in 2019$$,
   $$economie-vwo-2022-ii-zelfstandigen-zonder-personeel-context3.png$$,
   $$Figuur 1 Lorenzcurven van zzp’ers in 2019
verticale as: inkomen in % van het totaal (0-100); horizontale as: aantal personen in % van het totaal (0-100)
Twee Lorenzcurven onder de diagonaal (gelijkheidslijn); de doorgetrokken lijn (primaire inkomensverdeling) ligt verder van de diagonaal dan de stippellijn (secundaire inkomensverdeling). Beide curven beginnen bij (0, 0) en eindigen bij (100, 100).
Legenda: doorgetrokken lijn = primaire inkomensverdeling; stippellijn = secundaire inkomensverdeling$$, 'inline'),
  ('f1a4f0b2-d42b-4241-8316-b48178476e7a', '418b6293-cfe9-4313-93b8-f84f1bcd95b5', $$verlaging heffingskorting zelfstandigen met € 2.000; progressief stelsel$$,
   $$economie-vwo-2022-ii-zelfstandigen-zonder-personeel-context4.png$$,
   $$Samira verwacht dat in 2022 de heffingskorting voor zelfstandigen met € 2.000 wordt verlaagd. Er is sprake van een progressief belastingstelsel.$$, 'inline'),
  ('53c4334d-e156-4ebf-a60f-a84cf31a9a96', '418b6293-cfe9-4313-93b8-f84f1bcd95b5', $$voorstel wettelijk minimumuurtarief voor zzp'ers$$,
   $$economie-vwo-2022-ii-zelfstandigen-zonder-personeel-context5.png$$,
   $$Ondanks de vele gewerkte uren, komt een deel van de zzp’ers onder de armoedegrens. Daarom pleiten de onderzoekers voor het invoeren van een wettelijk minimumuurtarief voor zzp’ers, net zoals het bestaande wettelijk minimumloon voor werknemers in loondienst.$$, 'inline'),
  ('22cc570c-6c0b-48ba-a492-0031e891b766', '418b6293-cfe9-4313-93b8-f84f1bcd95b5', $$model van de markt voor zzp'ers in 2022$$,
   $$economie-vwo-2022-ii-zelfstandigen-zonder-personeel-context6.png$$,
   $$De onderzoekers hebben een model gemaakt voor de markt van zzp’ers in 2022 om de gevolgen van hun voorstel te analyseren:$$, 'inline'),
  ('e52de695-7c9b-46ad-bb09-ce1cd982930a', '418b6293-cfe9-4313-93b8-f84f1bcd95b5', $$vraag- en aanbodvergelijking zzp-uren$$,
   $$economie-vwo-2022-ii-zelfstandigen-zonder-personeel-context7.png$$,
   $$Qv = -30U + 630 | Totaal gevraagd aantal uren naar zzp’ers in miljoenen per jaar
Qa = +20U – 50 | Totaal aangeboden aantal uren door zzp’ers in miljoenen per jaar
U | Uurtarief in euro’s$$, 'inline'),
  ('696eeec3-d284-4910-aab3-920e36032e1b', '418b6293-cfe9-4313-93b8-f84f1bcd95b5', $$model gaat uit van volledige mededinging: alleen laaggeschoolde arbeid$$,
   $$economie-vwo-2022-ii-zelfstandigen-zonder-personeel-context8.png$$,
   $$Jan en Samira beseffen dat hun model een forse vereenvoudiging is van de realiteit. Het model gaat uit van een arbeidsmarkt van volledige mededinging: ze stellen daarom dat dit model alleen voor laaggeschoolde arbeid geldt en niet voor hooggeschoolde arbeid.$$, 'inline'),
  ('37a6a60d-e5ea-4f5f-acd5-25dbf49983d9', '418b6293-cfe9-4313-93b8-f84f1bcd95b5', $$minimumtarief van 16 euro per uur: armoede en werkgelegenheid$$,
   $$economie-vwo-2022-ii-zelfstandigen-zonder-personeel-context9.png$$,
   $$Jan en Samira onderzoeken de gevolgen van de invoering van een minimumtarief voor zzp’ers van 16 euro per uur op twee punten: i het armoedeprobleem onder zzp’ers verminderen ii de totale werkgelegenheid beïnvloeden$$, 'inline'),
  ('aca42518-7eae-4d87-a347-5f1c49028f59', '418b6293-cfe9-4313-93b8-f84f1bcd95b5', $$omzetontwikkeling als indicator voor het armoedeprobleem$$,
   $$economie-vwo-2022-ii-zelfstandigen-zonder-personeel-context10.png$$,
   $$Ze gebruiken de omzetontwikkeling van de zzp’ers als de indicator voor het armoedeprobleem onder zzp’ers.$$, 'inline'),
  ('1300c5bf-88ee-4143-953f-c31dd102caad', 'eeb8de94-885d-45ae-91c8-9e82c207b9e3', $$inleiding: klimaatplan; Leport wil CO₂ van vier bedrijven afvangen en opslaan$$,
   $$economie-vwo-2022-ii-co2-ondergronds-context1.png$$,
   $$De overheid van een land heeft een klimaatplan opgesteld waarin een totale landelijke reductie van 49% van de CO₂-uitstoot in 2030 is opgenomen. Leport, het bedrijf dat een grote haven exploiteert, wil samenwerken met vier grote bedrijven in het havengebied om de CO₂- uitstoot bij die vier bedrijven af te vangen en op te slaan in een oud gasveld diep onder de grond in de zee.$$, 'inline'),
  ('9302c28c-0ceb-425e-ae5a-761139b8dcaa', 'eeb8de94-885d-45ae-91c8-9e82c207b9e3', $$schema: pijpleiding van vier bedrijven naar opslaglocatie in zee$$,
   $$economie-vwo-2022-ii-co2-ondergronds-context2.png$$,
   $$Schema: vier bedrijven (bedrijf 1, 2, 3 en 4) zijn met pijpen aangesloten op de transportpijpleiding van Leport voor afvangen CO₂ naar de opslaglocatie in zee.$$, 'inline'),
  ('50a4782b-6e66-4e50-843e-825acdd55f61', 'eeb8de94-885d-45ae-91c8-9e82c207b9e3', $$Leport investeert € 450 miljoen; tarief per ton CO₂$$,
   $$economie-vwo-2022-ii-co2-ondergronds-context3.png$$,
   $$Leport investeert € 450 miljoen voor de aanleg van een pijpleiding. Leport verzorgt het onderhoud en transport en vraagt aan de vier deelnemende bedrijven een tarief per ton CO₂. De vier bedrijven moeten zelf investeren in eigen afvanginstallaties. De vier bedrijven produceren ieder evenveel CO₂. Econoom Sacha Dumas presenteert de volgende gegevens:$$, 'inline'),
  ('1afabd09-d968-4c36-b002-7a4d2da45a73', 'eeb8de94-885d-45ae-91c8-9e82c207b9e3', $$tabel: gegevens aanleg pijpleiding, afvangen CO₂ en emissie$$,
   $$economie-vwo-2022-ii-co2-ondergronds-context4.png$$,
   $$Aanleg pijpleiding en capaciteit
investering aanleg pijpleiding door Leport | € 450 miljoen
maximale opslagcapaciteit in leeg gasveld | 37 miljoen ton
Afvangen CO₂
totale investering afvanginstallatie per bedrijf | € …
investeringsbedrag afvanginstallatie per bedrijf per ton CO₂ | € 65
tarief voor onderhoud en transport per ton CO₂ | € 10
totale productie CO₂ van de vier bedrijven samen per jaar | 2,4 miljoen ton
Emissie CO₂
emissierecht per ton CO₂ (Om een ton CO₂ uit te kunnen stoten, moeten bedrijven daartoe uitstootrechten kopen bij de overheid) | € 25$$, 'inline'),
  ('271ee002-8928-4e45-ba65-c5cc90508d45', 'eeb8de94-885d-45ae-91c8-9e82c207b9e3', $$terugtrekken bedrijf, berovingsprobleem en dreiging met opzegging$$,
   $$economie-vwo-2022-ii-co2-ondergronds-context5.png$$,
   $$Als een van de bedrijven zich na de aanleg van de installaties zou terugtrekken zou dit voor de overgebleven bedrijven betekenen dat ze elk een hoger transporttarief moeten gaan betalen, zodat Leport de pijpleiding kostendekkend houdt. Bij een mogelijke verhoging van het tarief kunnen de deelnemende bedrijven dreigen met opzegging van de samenwerking. Dumas concludeert:
i Leport kan te maken krijgen met een berovingsprobleem.
ii De dreiging om de samenwerking op te zeggen is niet geloofwaardig.$$, 'inline'),
  ('74c6184f-5db8-490d-8b5f-9336b621806d', 'eeb8de94-885d-45ae-91c8-9e82c207b9e3', $$aandeelhouders: principaal-agentprobleem tussen Leport en de bedrijven$$,
   $$economie-vwo-2022-ii-co2-ondergronds-context6.png$$,
   $$Aandeelhouders van de vier bedrijven zijn kritisch op de plannen: “Leport en de deelnemende bedrijven schatten de onderhouds- en transportkosten te laag in. Deze zullen hoger uitvallen als gevolg van een principaal- agentprobleem tussen Leport en de deelnemende bedrijven.” Leport en de deelnemende bedrijven weerspreken deze stelling: “We hebben in het contract een clausule opgenomen die het principaal-agentprobleem oplost.”$$, 'inline'),
  ('e7cb5bf7-69c8-4715-9e12-8b22c20227dc', 'eeb8de94-885d-45ae-91c8-9e82c207b9e3', $$subsidie van de minister in het eerste jaar$$,
   $$economie-vwo-2022-ii-co2-ondergronds-context7.png$$,
   $$De minister van Milieu overweegt een subsidie in het eerste jaar voor de deelnemende bedrijven omdat anders de doelstelling niet wordt gehaald. Die subsidie beoogt het verschil in uitgaven te dekken ten opzichte van de situatie waarbij geen CO₂ wordt afgevangen.$$, 'inline'),
  ('b6193172-1817-48db-a652-54a69b938651', 'eeb8de94-885d-45ae-91c8-9e82c207b9e3', $$argumenten van milieuorganisaties tegen subsidie$$,
   $$economie-vwo-2022-ii-co2-ondergronds-context8.png$$,
   $$Milieuorganisaties beargumenteren dat subsidie voor afvang en opslag van CO₂ een oplossing is voor de korte termijn, want het voorkomt het probleem van de uitstoot van CO₂ op langere termijn totaal niet. Daarnaast beargumenteren ze dat een subsidie helemaal niet nodig is, gegeven de marginale kosten van de productie van een ton CO₂ na aanleg van de afvanginstallatie.$$, 'inline'),
  ('b908803f-90ce-40bd-a575-58a9a4ac9e87', 'e3411297-5baf-4c73-a390-0b9a3ec6fcf8', $$inleiding: pensioenvoorziening uit AOW, aanvullend pensioen en eigen besparingen$$,
   $$economie-vwo-2022-ii-drie-pensioenscenarios-context1.png$$,
   $$In een land bestaat de pensioenvoorziening uit:
- een AOW uitkering voor iedere inwoner vanaf het 67ste levensjaar
- een aanvullend pensioen voor de werknemers in loondienst
- eigen (aanvullende) besparingen$$, 'inline'),
  ('6cbe4d60-ec88-495a-9556-cc730a88275a', 'e3411297-5baf-4c73-a390-0b9a3ec6fcf8', $$AOW via omslagstelsel; begrotingstekort van € 12 miljard$$,
   $$economie-vwo-2022-ii-drie-pensioenscenarios-context2.png$$,
   $$De AOW wordt in dit land gefinancierd volgens het omslagstelsel. De werkenden betalen daarnaast aanvullend pensioenpremies (belastingvrij) die worden belegd door een pensioenfonds. Door de toenemende vergrijzing moet de overheid het aankomende jaar een begrotingstekort dichten van € 12 miljard. Het Planbureau (PB) heeft drie scenario’s opgesteld voor de overheid om te bezuinigen op de AOW (zie de tabellen).$$, 'inline'),
  ('0f91f669-e0a0-489b-9656-416bb3a425ad', 'e3411297-5baf-4c73-a390-0b9a3ec6fcf8', $$tabel 1: drie scenario's om te bezuinigen op de AOW$$,
   $$economie-vwo-2022-ii-drie-pensioenscenarios-context3.png$$,
   $$Tabel 1 Drie scenario’s om te bezuinigen op de AOW
1. Verlaag de AOW-uitkering tot het niveau van een bijstandsuitkering. Een bijstandsuitkering is een (minimum)uitkering voor mensen die niet in hun levensonderhoud kunnen voorzien en die niet in aanmerking komen voor een andere uitkering.
2. Fiscaliseer de AOW-uitkering. Het totale tarief in de eerste schijf (zie tabel 3) blijft gelijk maar het premietarief wordt verlaagd naar 7,5%.
3. Verhoog de AOW-leeftijd naar 69 jaar.$$, 'inline'),
  ('d951f6a1-dd93-4c4b-8a17-566ad9e36044', 'e3411297-5baf-4c73-a390-0b9a3ec6fcf8', $$tabel 2: maandelijkse AOW- en bijstandsuitkeringen in 2020$$,
   $$economie-vwo-2022-ii-drie-pensioenscenarios-context4.png$$,
   $$Tabel 2 Maandelijkse AOW- en bijstandsuitkeringen in 2020
Soort huishouden | Brutobedrag bijstandsuitkering | Brutobedrag AOW-uitkering | Verdeling AOW-gerechtigden naar woonsituatie¹⁾
Alleenstaande | € 1.025 | € 1.128 | 39%
Samenwonend | € 745 | € 843 | 61%
¹⁾ als percentage van in totaal 3,4 miljoen AOW-gerechtigden$$, 'inline'),
  ('c3148b02-a51a-4eca-a914-26cc4980540e', 'e3411297-5baf-4c73-a390-0b9a3ec6fcf8', $$tabel 3: inkomstenbelastingtarieven in 2020$$,
   $$economie-vwo-2022-ii-drie-pensioenscenarios-context5.png$$,
   $$Tabel 3 Inkomstenbelastingtarieven in 2020
| Belastbaar inkomen | premietarief | totaal tarief (belasting en premies)
Schijf 1 | € 0 tot € 18.000 | 17,9% | 37,1%
Schijf 2 | € 18.000 tot € 60.000 | 11,6% | 40,4%
Schijf 3 | vanaf € 60.000 | | 49,5%$$, 'inline'),
  ('f7c1f385-c2d9-408a-b1ed-743e6a2daf03', 'e3411297-5baf-4c73-a390-0b9a3ec6fcf8', $$Matella: verplichte solidariteit tussen generaties onder druk$$,
   $$economie-vwo-2022-ii-drie-pensioenscenarios-context6.png$$,
   $$Econoom Izzy Matella van het PB constateert het volgende: “De verplichte solidariteit tussen generaties komt door de financiering van het omslagstelsel onder druk te staan.”$$, 'inline'),
  ('4011183a-d4bc-4477-84f2-4e6105826935', 'e3411297-5baf-4c73-a390-0b9a3ec6fcf8', $$AOW'ers betalen alleen belasting en geen premie$$,
   $$economie-vwo-2022-ii-drie-pensioenscenarios-context7.png$$,
   $$De groep AOW’ers betaalt over hun inkomen alleen belasting en geen premie.$$, 'inline'),
  ('a9190802-0ca7-4d8c-a739-e2ccf259c3bf', 'e3411297-5baf-4c73-a390-0b9a3ec6fcf8', $$Matella: scenario 3 tijdens hoogconjunctuur en krappe arbeidsmarkt$$,
   $$economie-vwo-2022-ii-drie-pensioenscenarios-context8.png$$,
   $$Econoom Matella stelt dat scenario 3 maatschappelijk wordt geaccepteerd als het wordt ingevoerd tijdens een hoogconjunctuur met een krappe arbeidsmarkt. Ze concludeert het volgende: “Ten eerste zal het invoeren van deze maatregel ervoor zorgen dat de werkgelegenheid stijgt. Daarnaast zal op termijn de concurrentiepositie van bedrijven worden verbeterd waardoor de werkgelegenheid extra zal stijgen.”$$, 'inline'),
  ('d121dd9a-547a-4e68-b30a-80220acc829c', 'cd7b07fa-2d3c-490d-bf6a-a7ca39459d50', $$inleiding: gemeente verbouwt textielfabriek van 25.000 m² voor startups$$,
   $$economie-vwo-2022-ii-strijd-om-startups-context1.png$$,
   $$De gemeente Berndonk ziet startups (startende ondernemers) als de motor van de lokale economie. Om meer startups aan te trekken, investeert de gemeente in de renovatie en verbouwing van een verlaten textielfabriek ter grootte van 25.000 vierkante meter (m²). De fabriek wordt geschikt gemaakt voor de vestiging van uitsluitend startende ondernemers.$$, 'inline'),
  ('96618076-1576-4cef-acd3-29aa94fa752f', 'cd7b07fa-2d3c-490d-bf6a-a7ca39459d50', $$initieel verlies, maar positieve externe effecten op lange termijn$$,
   $$economie-vwo-2022-ii-strijd-om-startups-context2.png$$,
   $$De gemeente begroot bij de verbouwing en verkoop van de fabriek een initieel verlies. Op de lange termijn verwacht de gemeente geen verlies vanwege het optreden van positieve externe effecten.$$, 'inline'),
  ('c83ad1c7-9c10-4bbe-93be-8364b9a75b5b', 'cd7b07fa-2d3c-490d-bf6a-a7ca39459d50', $$prijsafzetfunctie van de gemeente$$,
   $$economie-vwo-2022-ii-strijd-om-startups-context3.png$$,
   $$De gemeente gaat voor de prijsstelling bij verkoop van bedrijfsruimte uit van de volgende prijsafzetfunctie:$$, 'inline'),
  ('786d04bd-5ee6-4001-ac2f-cef36c954318', 'cd7b07fa-2d3c-490d-bf6a-a7ca39459d50', $$figuur 1: vraag en aanbod naar bedrijfsruimte$$,
   $$economie-vwo-2022-ii-strijd-om-startups-context4.png$$,
   $$Figuur 1 Vraag en aanbod naar bedrijfsruimte
Dalende vraaglijn GO = 500 - 0,008Q; verticale stippellijn bij Q = 25.000 (het aanbod).
Legenda:
P = de prijs van één m² bedrijfsruimte
Q = de hoeveelheid m² bedrijfsruimte$$, 'inline'),
  ('254ffee7-72de-42a7-97f1-45b8597fbf88', 'cd7b07fa-2d3c-490d-bf6a-a7ca39459d50', $$kosten van de verbouwing en twee voorstellen A en B van de wethouder$$,
   $$economie-vwo-2022-ii-strijd-om-startups-context5.png$$,
   $$De kosten van de verbouwing bedragen € 200 per m². De vaste (constante) kosten (voor de aanleg van de infrastructuur) bedragen € 3.500.000. De wethouder van Berndonk overweegt voor de verkoop twee voorstellen: A. De gemeente stelt een prijs vast waarbij alle bedrijfsruimte wordt verkocht. De mogelijke verliezen worden gedragen door de gemeente. B. De gemeente stelt een prijs vast waarbij het verlies van het project wordt geminimaliseerd. Daarbij geldt de eis dat de minimale bezetting van de fabrieksruimte 80% van de beschikbare ruimte moet zijn.$$, 'inline'),
  ('b1539c55-84b3-4105-9672-d780d5f020f3', 'cd7b07fa-2d3c-490d-bf6a-a7ca39459d50', $$nieuw voorstel: veiling met gesloten enveloppen$$,
   $$economie-vwo-2022-ii-strijd-om-startups-context6.png$$,
   $$Nog voor de verkoop blijkt de vraag naar de bedrijfsruimtes groter te zijn dan verwacht. De wethouder komt daarom met een nieuw voorstel: “We bieden de bedrijfsruimte aan in de vorm van een veiling: bedrijven geven in een gesloten envelop aan hoeveel m² ze willen kopen en welke prijs zij hiervoor willen betalen. Asymmetrische informatie en risicoaversie zorgen ervoor dat ondernemers hun maximale betalingsbereidheid aangeven. Als gemeente voorkomen we zo verlies.”$$, 'inline'),
  ('a142a55f-8bb9-4f9c-aa09-54eb763c1b3e', 'cd7b07fa-2d3c-490d-bf6a-a7ca39459d50', $$de veiling verloopt succesvol$$,
   $$economie-vwo-2022-ii-strijd-om-startups-context7.png$$,
   $$De veiling verloopt succesvol en geheel naar de verwachting van de wethouder.$$, 'inline'),
  ('d22f3a34-99f8-448c-ae28-3422da803dda', '70fb38e9-ac7b-4341-8ee8-205cabc54f25', $$inleiding: conjunctuuranalyse 2018 aan de hand van CBS-tabellen$$,
   $$economie-vwo-2022-ii-een-teken-van-conjunctuur-context1.png$$,
   $$Macro-economen gebruiken onder andere de publicaties van het Centraal Bureau voor de Statistiek (CBS) om de conjuncturele ontwikkeling te kunnen analyseren en de regering te kunnen adviseren. In 2018 is in kwartaal 3 de economische groei lager dan de trendmatige groei. In 2018 analyseren economen de conjunctuur aan de hand van tabellen 1 en 2.$$, 'inline'),
  ('cbef95a4-76a1-484e-b9c7-44041e3c97e2', '70fb38e9-ac7b-4341-8ee8-205cabc54f25', $$tabel 1: macro-economische variabelen Nederland, derde kwartaal 2018$$,
   $$economie-vwo-2022-ii-een-teken-van-conjunctuur-context2.png$$,
   $$Tabel 1 Enkele macro-economische variabelen van Nederland in het derde kwartaal van 2018
Variabele | Mutatie in procenten ten opzichte van het tweede kwartaal
Volume bruto binnenlands product (= reëel bbp) | +0,20 (gewogen gemiddelde)
Exportvolume | +0,50
Consumptievolume huishoudens | +0,20
Volume bruto overheidsbestedingen | +0,10
Volume bruto bedrijfsinvesteringen | -0,10
Importvolume | -0,40
Inflatie | +0,30$$, 'inline'),
  ('5735ead0-1c6f-460d-9cfb-c5a30f5307ed', '70fb38e9-ac7b-4341-8ee8-205cabc54f25', $$tabel 2: conjunctuurindicatoren Nederland, derde kwartaal 2018$$,
   $$economie-vwo-2022-ii-een-teken-van-conjunctuur-context3.png$$,
   $$Tabel 2 Enkele conjunctuurindicatoren van Nederland in het derde kwartaal van 2018
Variabele | Ontwikkeling ten opzichte van het tweede kwartaal in 2018
Orderportefeuille industrie | --
Aantal faillissementen | -
Omzet uitzendbranche | +
Producentenvertrouwen | -
Gemiddelde verkoopprijs nieuwbouwwoning | ++
Toelichting: ++ = grote toename, + = toename, - = afname, -- = grote afname$$, 'inline'),
  ('8b751fbd-3cb8-4ff7-a7bb-a7349a4594a3', '70fb38e9-ac7b-4341-8ee8-205cabc54f25', $$Nederland is een open economie$$,
   $$economie-vwo-2022-ii-een-teken-van-conjunctuur-context4.png$$,
   $$De Nederlandse economie is open en daardoor is de conjunctuur van Nederland in hoge mate afhankelijk van de conjuncturele ontwikkeling van het buitenland.$$, 'inline'),
  ('6404d2c7-574b-40e4-81fd-8f4c087ee7cc', '70fb38e9-ac7b-4341-8ee8-205cabc54f25', $$Bootsman en Paridons over onzekerheden in de Duitse economie$$,
   $$economie-vwo-2022-ii-een-teken-van-conjunctuur-context5.png$$,
   $$Economen Bootsman en Paridons vrezen voor de gevolgen van de onzekerheden in de Duitse economie. Ze discussiëren over toekomstige groeidata van de Nederlandse economie. Bootsman ziet de inflatie toenemen, en beweert daarover het volgende:$$, 'inline'),
  ('ec7d9486-965b-4d25-b0c8-8efb803ecd52', '70fb38e9-ac7b-4341-8ee8-205cabc54f25', $$Bootsman: relatief hoge inflatie door wisselkoersverandering$$,
   $$economie-vwo-2022-ii-een-teken-van-conjunctuur-context6.png$$,
   $$Bootsman: “Ondanks de laagconjunctuur is er een relatief hoge inflatie dankzij een wisselkoersverandering van de euro ten opzichte van de dollar.”$$, 'inline'),
  ('629becb9-cbec-4372-a31e-37d4b0e09245', '70fb38e9-ac7b-4341-8ee8-205cabc54f25', $$Paridons: krimp Duits reëel bbp drukt Nederlandse groei$$,
   $$economie-vwo-2022-ii-een-teken-van-conjunctuur-context7.png$$,
   $$Paridons: “Omdat het reële bbp van Duitsland in kwartaal 3 ten opzichte van kwartaal 2 met 0,1% is gekrompen – en ik denk dat deze ontwikkeling zich in Duitsland voortzet – kan de groei van de Nederlandse economie hiermee nog meer onder de trend komen.”$$, 'inline'),
  ('ed15c813-a54e-4478-a36b-1a6479536003', '01ae49b0-7a5c-4b98-a03f-7098def78fac', $$inleiding: heffing van 13% op suikerhoudende frisdrank in de Filipijnen$$,
   $$economie-vwo-2022-ii-zoet-gedronken-zuur-betaald-context1.png$$,
   $$Onderzoekers van de Wereldgezondheidsorganisatie hebben aangetoond dat overmatige consumptie van suikerhoudende frisdranken leidt tot veel overgewicht en diabetes in de Filipijnen. De Filipijnse overheid heeft daarom een heffing van 13% op de prijs van 45 peso’s per liter suikerhoudende frisdrank gelegd.$$, 'inline'),
  ('f6c684b1-7c93-4df9-bab2-f2dc1c653485', '01ae49b0-7a5c-4b98-a03f-7098def78fac', $$gevolgen van de heffing per inkomensgroep (kwintielen)$$,
   $$economie-vwo-2022-ii-zoet-gedronken-zuur-betaald-context2.png$$,
   $$Omdat de Filipijnen een grote mate van inkomensongelijkheid kennen, kijken de onderzoekers ook naar de gevolgen van de heffing per inkomensgroep. Ze verdelen daartoe de bevolking in vijf bevolkingsgroepen van gelijke grootte (kwintielen).$$, 'inline'),
  ('1d0fb8d5-2962-42bb-8327-d5057a51cf8f', '01ae49b0-7a5c-4b98-a03f-7098def78fac', $$tabel 1: inkomen, prijselasticiteit, consumptie en eigen bijdrage per kwintiel$$,
   $$economie-vwo-2022-ii-zoet-gedronken-zuur-betaald-context3.png$$,
   $$Tabel 1 Gegevens in de uitgangssituatie zonder heffing en een prijs van 45 peso’s voor een liter suikerhoudende frisdrank
Kwintiel | 1 | 2 | 3 | 4 | 5
Gemiddeld inkomen in peso’s per jaar | 11.762 | 29.705 | 44.915 | 72.541 | 91.138
prijselasticiteit suikerhoudende frisdrank | -1,50 | -1,41 | -1,24 | -1,09 | -0,97
dagelijkse consumptie suikerhoudende frisdrank | 0,13 liter | 0,18 liter | 0,21 liter | 0,26 liter | 0,29 liter
toekomstig plan eigen bijdrage zorg in % van de zorgkosten | 20% | 37% | 52% | 71% | 83%$$, 'inline'),
  ('036689c0-3504-4ea4-ba33-c0a257abee4a', '01ae49b0-7a5c-4b98-a03f-7098def78fac', $$plan: eigen bijdrage zorg progressiever maken$$,
   $$economie-vwo-2022-ii-zoet-gedronken-zuur-betaald-context4.png$$,
   $$De huidige eigen bijdrage is 20% van de zorgkosten. De onderzoekers schrijven een plan voor de toekomst: “Door de eigen bijdrage in procenten van de zorgkosten progressiever te maken verwachten we een forse vermindering van overgewicht en diabetes.”$$, 'inline'),
  ('ab09f939-c2a5-4006-96f6-2e05f534c75a', '01ae49b0-7a5c-4b98-a03f-7098def78fac', $$verschil in prijselasticiteit tussen kwintiel 1 en 5$$,
   $$economie-vwo-2022-ii-zoet-gedronken-zuur-betaald-context5.png$$,
   $$De onderzoekers bekijken het verschil in de prijselasticiteiten tussen kwintiel 1 en kwintiel 5 en tonen figuur 1.$$, 'inline'),
  ('438fe96e-1799-4f1b-9a3a-fc37d62ee07d', '01ae49b0-7a5c-4b98-a03f-7098def78fac', $$figuur 1: vraaglijnen van kwintiel 1 en kwintiel 5$$,
   $$economie-vwo-2022-ii-zoet-gedronken-zuur-betaald-context6.png$$,
   $$Figuur 1 Vraaglijnen van kwintiel 1 en kwintiel 5
Twee dalende vraaglijnen, Qv A (links, lager) en Qv B (rechts, hoger); horizontale stippellijn bij P = 45.
verticale as: P; horizontale as: Qv (vraag naar suikerhoudende frisdrank)$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('f41812f9-7eb4-4315-9384-7c3e014cf716', '418b6293-cfe9-4313-93b8-f84f1bcd95b5', 1,
   '[{"domain": "Welvaart en groei", "subdomain": "Ongelijkheid en herverdeling"}]'::jsonb,
   '["Lorenzcurve", "primaire inkomensverdeling", "negatief inkomen", "inkomensongelijkheid", "kwintielen"]'::jsonb,
   $$Uitleggen hoe een Lorenzcurve moet worden aangepast als de laagste inkomensgroep een negatief inkomen heeft.$$,
   $$economie-vwo-2022-ii-zelfstandigen-zonder-personeel-vraag1.png$$, $$2p 1 Leg uit hoe de Lorenzcurve van de primaire inkomens kan worden gecorrigeerd om aan Samira’s kanttekening tegemoet te komen.$$, array['f949b95a-edb7-45a2-9813-532736b1194c', 'eed39c77-4f25-4ebc-9467-61eccf9b6e48', '86bcfbb0-99b1-476b-84ad-01d81d5f022d']::uuid[]),
  ('ba46b8ce-85ff-46d0-adad-d70a0c575dc1', '418b6293-cfe9-4313-93b8-f84f1bcd95b5', 2,
