   $$economie-vwo-2022-ii-zelfstandigen-zonder-personeel-vraag4.png$$, $$2p 4 Verklaar de stelling van Jan en Samira.$$, array['22cc570c-6c0b-48ba-a492-0031e891b766', 'e52de695-7c9b-46ad-bb09-ce1cd982930a', '696eeec3-d284-4910-aab3-920e36032e1b']::uuid[]),
  ('3a4ba338-d627-4433-9e6d-ee89d828f1da', '418b6293-cfe9-4313-93b8-f84f1bcd95b5', 5,
