   $$economie-vwo-2022-ii-drie-pensioenscenarios-vraag14.png$$, $$2p 14 Leidt scenario 2 tot nivellering of denivellering van de secundaire inkomens binnen de totale groep van gepensioneerden? Beargumenteer je keuze.$$, array['0f91f669-e0a0-489b-9656-416bb3a425ad', 'c3148b02-a51a-4eca-a914-26cc4980540e', '4011183a-d4bc-4477-84f2-4e6105826935']::uuid[]),
